import React, { useEffect, useRef, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { Activity, ArrowDownLeft, ArrowRight, ArrowUpRight, CalendarDays, Check, CheckCircle2,
  ChevronLeft, ChevronRight, CircleDollarSign, Clock3, FileText, HeartPulse, LayoutDashboard,
  LogOut, Menu, PackagePlus, Pill, Plus, Search, ShieldCheck, SlidersHorizontal, Stethoscope,
  Trash2, TrendingUp, Users, Wallet, X, AlertCircle, LoaderCircle, RefreshCw, Pencil, Sparkles } from 'lucide-react';
import { api, hasToken, send, setToken } from './api';

const money = value => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 2 }).format(Number(value || 0));
const clinicDate = () => new Date().toLocaleDateString('sv-SE', { timeZone: 'Asia/Kolkata' });
const nextDate = () => { const d = new Date(`${clinicDate()}T12:00:00`); d.setDate(d.getDate() + 1); return d.toLocaleDateString('sv-SE'); };
const dateLabel = value => new Date(`${value}T12:00:00`).toLocaleDateString('en-IN', { month: 'short', day: 'numeric', year: 'numeric' });
const initials = name => name.split(' ').map(word => word[0]).slice(0, 2).join('');
const emptyPatient = { first_name: '', last_name: '', date_of_birth: '', gender: 'Female', blood_group: '', phone: '', email: '', address: '', emergency_contact_phone: '' };
const navItems = [
  ['overview', 'Overview', LayoutDashboard], ['appointments', 'Appointments', CalendarDays],
  ['patients', 'Patient registry', Users], ['consultations', 'Consultations', Stethoscope],
  ['pharmacy', 'Pharmacy', Pill], ['billing', 'Billing', Wallet], ['reports', 'Reports & insights', TrendingUp],
];

function useData(path, enabled = true) {
  return useQuery({ queryKey: [path], queryFn: () => api(path), enabled });
}

function Status({ value }) {
  return <span className={`status status-${value?.toLowerCase()}`}><i />{value?.replaceAll('_', ' ')}</span>;
}

function Loading() {
  return <div className="loading" role="status"><LoaderCircle className="spin" size={22} /> Loading clinic data…</div>;
}

function Empty({ title = 'Nothing here yet', text = 'Records will appear as your clinic gets to work.' }) {
  return <div className="empty"><Activity size={30} /><h3>{title}</h3><p>{text}</p></div>;
}

function ErrorState({ error, retry }) {
  return <div className="error-state" role="alert"><AlertCircle size={20} /><div><strong>We couldn’t load this view.</strong><p>{error.message}</p></div><button className="btn secondary" onClick={retry}>Try again</button></div>;
}

function Field({ label, children, ...props }) {
  return <label className="field"><span>{label}</span>{children || <input {...props} />}</label>;
}

function FormFooter({ busy, disabled, label = 'Save changes', close }) {
  return <footer className="form-footer"><button type="button" className="btn secondary" onClick={close} disabled={busy}>Cancel</button><button className="btn primary" disabled={busy || disabled}>{busy ? <LoaderCircle className="spin" size={16} /> : <Check size={16} />}{busy ? 'Saving…' : label}</button></footer>;
}

function Modal({ title, subtitle, children, close, wide }) {
  const ref = useRef();
  useEffect(() => { const dialog = ref.current; dialog.showModal(); return () => dialog.close(); }, []);
  return <dialog ref={ref} className={`modal ${wide ? 'modal-wide' : ''}`} onCancel={e => { e.preventDefault(); close(); }} onClick={e => { if (e.target === ref.current) close(); }}>
    <div className="modal-content"><header className="modal-header"><div><span className="eyebrow">MEDCONNECT WORKSPACE</span><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-btn" aria-label="Close dialog" onClick={close}><X size={20} /></button></header>{children}</div>
  </dialog>;
}

function Login({ onLogin }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const mutation = useMutation({ mutationFn: () => send('/auth/login', 'POST', { email, password }), onSuccess: data => { setToken(data.access_token); onLogin(data.user); } });
  return <main className="login-page"><section className="login-story"><a className="brand" href="#"><span className="brand-icon"><HeartPulse size={28} /></span><span>MedConnect<small>CLINIC MANAGEMENT</small></span></a>
    <div className="login-copy"><span className="pill-label"><i /> A MORE CONNECTED CLINIC</span><h1>Less friction.<br />More room<br />for <em>care.</em></h1><p>One thoughtful workspace for every appointment, every encounter, and everything in between.</p>
      <div className="story-stats"><div><CalendarDays /><span>Seamless<br /><b>scheduling</b></span></div><div><ShieldCheck /><span>Connected<br /><b>clinical records</b></span></div><div><Pill /><span>Smarter<br /><b>inventory</b></span></div></div>
    </div><div className="login-orbit orbit-one" /><div className="login-orbit orbit-two" /><div className="story-footer">MEDCONNECT <span>Group-11 · DBMS Course Project</span></div></section>
    <section className="login-panel"><div className="login-card"><span className="login-symbol"><Stethoscope size={30} /></span><span className="eyebrow">YOUR CLINIC. IN SYNC.</span><h2>Welcome back.</h2><p>Sign in to your clinic workspace to get started.</p><form onSubmit={e => { e.preventDefault(); mutation.mutate(); }}>
      <Field label="Email address" type="email" autoComplete="username" value={email} onChange={e => setEmail(e.target.value)} placeholder="you@medconnect.local" required />
      <Field label="Password" type="password" autoComplete="current-password" value={password} onChange={e => setPassword(e.target.value)} placeholder="Enter your password" required />
      {mutation.error && <p className="form-error" role="alert">{mutation.error.message}</p>}
      <button className="btn primary login-submit" disabled={mutation.isPending}>{mutation.isPending ? <LoaderCircle className="spin" size={18} /> : <>Open workspace <ArrowRight size={18} /></>}</button>
    </form><div className="login-note"><ShieldCheck size={16} /><span>For authorized clinic staff and doctors.<br />Demonstration accounts are listed in the project README.</span></div></div><div className="login-bottom">Thoughtfully connected. From reception to recovery.</div></section>
  </main>;
}

function PatientForm({ patient, submit, busy, error, close }) {
  const [form, setForm] = useState(patient ? Object.fromEntries(Object.keys(emptyPatient).map(k => [k, patient[k] || ''])) : emptyPatient);
  const update = key => e => setForm({ ...form, [key]: e.target.value });
  return <form onSubmit={e => { e.preventDefault(); submit({ ...form, blood_group: form.blood_group || null, email: form.email || null, emergency_contact_phone: form.emergency_contact_phone || null }); }}>
    <div className="form-grid"><Field label="First name" value={form.first_name} onChange={update('first_name')} maxLength={50} required /><Field label="Last name" value={form.last_name} onChange={update('last_name')} maxLength={50} required />
      <Field label="Date of birth" type="date" min="1900-01-01" max={clinicDate()} value={form.date_of_birth} onChange={update('date_of_birth')} required />
      <Field label="Gender"><select value={form.gender} onChange={update('gender')}>{['Female', 'Male', 'Other'].map(v => <option key={v}>{v}</option>)}</select></Field>
      <Field label="Blood group"><select value={form.blood_group} onChange={update('blood_group')}><option value="">Not recorded</option>{['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'].map(v => <option key={v}>{v}</option>)}</select></Field>
      <Field label="Phone number" type="tel" minLength={7} maxLength={20} value={form.phone} onChange={update('phone')} required />
      <Field label="Email address" type="email" value={form.email} onChange={update('email')} maxLength={100} /><Field label="Emergency contact" type="tel" value={form.emergency_contact_phone} onChange={update('emergency_contact_phone')} maxLength={20} />
      <div className="full"><Field label="Address"><textarea value={form.address} onChange={update('address')} maxLength={1000} required rows={2} /></Field></div>
    </div>{error && <p className="form-error" role="alert">{error.message}</p>}<FormFooter busy={busy} label={patient ? 'Update patient' : 'Register patient'} close={close} /></form>;
}

function BookingForm({ appointment, doctors, submit, busy, error, close }) {
  const [patientSearch, setPatientSearch] = useState('');
  const patientQuery = useData(`/patients?q=${encodeURIComponent(patientSearch)}&limit=250`, !appointment);
  const [form, setForm] = useState({ patient_id: '', doctor_id: appointment?.doctor_id || '', appointment_date: appointment?.appointment_date || nextDate(), appointment_time: '', reason_for_visit: '' });
  const slots = useData(`/slots?doctor_id=${form.doctor_id}&appointment_date=${form.appointment_date}${appointment ? `&exclude_appointment_id=${appointment.appointment_id}` : ''}`, Boolean(form.doctor_id && form.appointment_date));
  const change = (key, value) => setForm(current => ({ ...current, [key]: value, ...(key === 'doctor_id' || key === 'appointment_date' ? { appointment_time: '' } : {}) }));
  return <form onSubmit={e => { e.preventDefault(); submit(appointment ? { appointment_date: form.appointment_date, appointment_time: form.appointment_time } : { ...form, patient_id: Number(form.patient_id), doctor_id: Number(form.doctor_id) }); }}>
    {appointment ? <div className="context-card"><span className="avatar">{initials(appointment.patient_name)}</span><div><strong>{appointment.patient_name}</strong><p>Dr. {appointment.doctor_name} · Currently {dateLabel(appointment.appointment_date)}, {appointment.appointment_time.slice(0, 5)}</p></div></div> : <div className="form-grid">
      <div className="full"><Field label="Find a registered patient" value={patientSearch} onChange={e => setPatientSearch(e.target.value)} placeholder="Search name or phone number" /></div>
      <div className="full"><Field label="Patient"><select required value={form.patient_id} onChange={e => change('patient_id', e.target.value)}><option value="">Select a patient</option>{patientQuery.data?.map(p => <option key={p.patient_id} value={p.patient_id}>{p.first_name} {p.last_name} · {p.phone} · #{p.patient_id}</option>)}</select></Field></div>
      <div className="full"><Field label="Treating doctor"><select required value={form.doctor_id} onChange={e => change('doctor_id', e.target.value)}><option value="">Select a doctor and specialty</option>{doctors.filter(d => d.status === 'Active').map(d => <option key={d.doctor_id} value={d.doctor_id}>Dr. {d.first_name} {d.last_name} · {d.dept_name} · {money(d.consultation_fee)}</option>)}</select></Field></div>
    </div>}
    <Field label="Appointment date" type="date" min={clinicDate()} value={form.appointment_date} onChange={e => change('appointment_date', e.target.value)} required />
    <div className="slot-section"><span className="field-label">Available times <small>IST · Asia/Kolkata</small></span>{!form.doctor_id ? <p className="muted">Choose a doctor to see available times.</p> : slots.isPending ? <Loading /> : slots.error ? <ErrorState error={slots.error} retry={slots.refetch} /> : slots.data?.length ? <div className="slot-grid">{slots.data.map(slot => <button key={slot.time} type="button" aria-pressed={form.appointment_time === slot.time} className={`slot ${form.appointment_time === slot.time ? 'selected' : ''}`} onClick={() => change('appointment_time', slot.time)}>{slot.time}<small>{slot.duration_minutes} min</small></button>)}</div> : <p className="inline-note">No available times on this date. Choose another day.</p>}</div>
    {!appointment && <Field label="Reason for visit"><textarea required maxLength={255} rows={2} value={form.reason_for_visit} onChange={e => change('reason_for_visit', e.target.value)} placeholder="What brings the patient in?" /></Field>}
    {error && <p className="form-error" role="alert">{error.message}<button type="button" className="text-btn" onClick={() => slots.refetch()}>Refresh available times</button></p>}
    <div className="inline-note"><ShieldCheck size={16} /> Your slot is confirmed after the booking is saved.</div>
    <FormFooter busy={busy} disabled={!form.appointment_time} label={appointment ? 'Reschedule appointment' : 'Confirm appointment'} close={close} />
  </form>;
}

function EncounterForm({ appointment, medicines, submit, busy, error, close }) {
  const [form, setForm] = useState({ symptoms: '', diagnosis: '', clinical_notes: '', instructions: '', items: [] });
  const update = key => e => setForm({ ...form, [key]: e.target.value });
  const updateItem = (index, key, value) => setForm({ ...form, items: form.items.map((item, i) => i === index ? { ...item, [key]: value } : item) });
  return <form onSubmit={e => { e.preventDefault(); submit({ ...form, items: form.items.map(item => ({ ...item, medicine_id: Number(item.medicine_id), quantity: Number(item.quantity), duration_days: Number(item.duration_days) })) }); }}>
    <div className="context-card"><span className="avatar">{initials(appointment.patient_name)}</span><div><strong>{appointment.patient_name}</strong><p>Encounter #{appointment.appointment_id} · {appointment.reason_for_visit}</p></div><Status value="In_Consultation" /></div>
    <div className="form-grid"><Field label="Presenting symptoms"><textarea rows={3} required maxLength={5000} value={form.symptoms} onChange={update('symptoms')} placeholder="Record presenting symptoms" /></Field><Field label="Diagnosis"><textarea rows={3} required maxLength={5000} value={form.diagnosis} onChange={update('diagnosis')} placeholder="Record the clinical assessment" /></Field><div className="full"><Field label="Clinical notes"><textarea rows={2} maxLength={10000} value={form.clinical_notes} onChange={update('clinical_notes')} placeholder="Observations and follow-up notes" /></Field></div></div>
    <div className="section-heading compact"><div><h3>Prescription</h3><p>Stock is deducted when the encounter is completed.</p></div><button type="button" className="btn secondary small" onClick={() => setForm({ ...form, items: [...form.items, { medicine_id: '', dosage: '', duration_days: 3, quantity: 1 }] })}><Plus size={15} /> Add medicine</button></div>
    {!form.items.length && <div className="inline-note">No medicines prescribed. You can complete a consultation without a prescription.</div>}
    {form.items.map((item, index) => <div className="prescription-line" key={index}>
      <Field label={`Medicine ${index + 1}`}><select value={item.medicine_id} onChange={e => updateItem(index, 'medicine_id', e.target.value)} required><option value="">Choose medicine</option>{medicines.filter(m => !m.expired).map(m => <option key={m.medicine_id} value={m.medicine_id} disabled={form.items.some((other, i) => i !== index && Number(other.medicine_id) === m.medicine_id)}>{m.name} · {m.stock_quantity} in stock · {money(m.unit_price)}</option>)}</select></Field>
      <Field label="Dosage" value={item.dosage} maxLength={50} onChange={e => updateItem(index, 'dosage', e.target.value)} placeholder="Dosage instructions" required />
      <Field label="Days" type="number" min={1} max={365} value={item.duration_days} onChange={e => updateItem(index, 'duration_days', e.target.value)} required /><Field label="Quantity" type="number" min={1} max={10000} value={item.quantity} onChange={e => updateItem(index, 'quantity', e.target.value)} required />
      <button type="button" className="icon-btn danger" aria-label={`Remove medicine ${index + 1}`} onClick={() => setForm({ ...form, items: form.items.filter((_, i) => i !== index) })}><Trash2 size={17} /></button>
    </div>)}
    <Field label="Prescription instructions"><textarea rows={2} maxLength={5000} value={form.instructions} onChange={update('instructions')} /></Field>
    <div className="inline-note"><ShieldCheck size={17} /> Completing saves the clinical record, dispenses medicines, and issues the invoice together. The completed record cannot be edited.</div>
    {error && <p className="form-error" role="alert">{error.message}</p>}<FormFooter busy={busy} label="Complete & issue invoice" close={close} />
  </form>;
}

function MedicineForm({ submit, busy, error, close }) {
  const [form, setForm] = useState({ name: '', category: 'Other', manufacturer: '', unit_price: '', stock_quantity: '', reorder_level: 20, expiry_date: '' });
  const change = key => e => setForm({ ...form, [key]: e.target.value });
  return <form onSubmit={e => { e.preventDefault(); submit({ ...form, stock_quantity: Number(form.stock_quantity), reorder_level: Number(form.reorder_level) }); }}><div className="form-grid">
    <Field label="Medicine name" value={form.name} onChange={change('name')} maxLength={100} required /><Field label="Category"><select value={form.category} onChange={change('category')}>{['Antibiotic', 'Analgesic', 'Antihistamine', 'Antipyretic', 'Cardiovascular', 'Antidiabetic', 'Supplements', 'Other'].map(v => <option key={v}>{v}</option>)}</select></Field>
    <Field label="Manufacturer" value={form.manufacturer} onChange={change('manufacturer')} required maxLength={100} /><Field label="Unit price (₹)" type="number" min={0} max={99999999.99} step="0.01" value={form.unit_price} onChange={change('unit_price')} required />
    <Field label="Opening stock" type="number" min={0} max={1000000} value={form.stock_quantity} onChange={change('stock_quantity')} required /><Field label="Reorder level" type="number" min={0} value={form.reorder_level} onChange={change('reorder_level')} required /><Field label="Expiry date" type="date" min={clinicDate()} value={form.expiry_date} onChange={change('expiry_date')} required />
  </div>{error && <p className="form-error" role="alert">{error.message}</p>}<FormFooter busy={busy} label="Add medicine" close={close} /></form>;
}

function ValueForm({ label, initial = '', numeric, submit, busy, error, close, button }) {
  const [value, setValue] = useState(initial);
  return <form onSubmit={e => { e.preventDefault(); submit(value); }}><Field label={label} type={numeric ? 'number' : 'text'} min={numeric === 'price' ? 0 : 1} step={numeric === 'price' ? '.01' : 1} value={value} onChange={e => setValue(e.target.value)} required />{error && <p className="form-error" role="alert">{error.message}</p>}<FormFooter busy={busy} label={button} close={close} /></form>;
}

function PaymentForm({ invoice, submit, busy, error, close }) {
  const [method, setMethod] = useState('UPI');
  return <form onSubmit={e => { e.preventDefault(); submit({ payment_method: method }); }}><div className="payment-amount"><span>INVOICE #{invoice.invoice_id} · {invoice.patient_name}</span><h2>{money(invoice.total_amount)}</h2><p>Consultation {money(invoice.consultation_fee)} + pharmacy {money(invoice.medicine_total)}</p></div><Field label="Payment method"><select value={method} onChange={e => setMethod(e.target.value)}>{['UPI', 'Cash', 'Card', 'Insurance', 'NetBanking'].map(v => <option key={v}>{v}</option>)}</select></Field><p className="muted">Records a payment received at the clinic. No online money transfer is made.</p>{error && <p className="form-error" role="alert">{error.message}</p>}<FormFooter busy={busy} label="Record payment" close={close} /></form>;
}

function History({ patient }) {
  const query = useData(`/patients/${patient.patient_id}/history`);
  if (query.isPending) return <Loading />;
  if (query.error) return <ErrorState error={query.error} retry={query.refetch} />;
  if (!query.data.length) return <Empty title="No clinical history yet" text="Completed consultations will appear here." />;
  return <div className="timeline">{query.data.map(r => <article key={r.record_id}><span className="timeline-dot"><Stethoscope size={15} /></span><div className="timeline-heading"><strong>{r.appointment_date ? dateLabel(r.appointment_date) : 'Imported record'}</strong><span>{r.dept_name}</span></div><h3>{r.diagnosis}</h3><p className="muted">Dr. {r.doctor_name} · Record #{r.record_id}</p><dl><dt>Symptoms</dt><dd>{r.symptoms}</dd>{r.clinical_notes && <><dt>Clinical notes</dt><dd>{r.clinical_notes}</dd></>}</dl>{r.prescribed_medications?.length > 0 && <div className="history-meds">{r.prescribed_medications.map((m, i) => <div key={i}><Pill size={15} /><span><strong>{m.medicine_name}</strong><small>{m.dosage} · {m.duration_days} days · Qty {m.quantity} · {money(m.unit_price)} / unit</small></span></div>)}</div>}{r.instructions && <p>{r.instructions}</p>}</article>)}</div>;
}

function AppointmentTable({ rows, user, open, action, compact = false }) {
  if (!rows.length) return <Empty title="A little breathing room" text="No appointments match this view. Try another date or book a new visit." />;
  return <div className="table-wrap"><table><thead><tr><th>Patient</th><th>{compact ? 'Time' : 'Date & time'}</th><th>Doctor / specialty</th><th>Status</th><th className="align-right">Action</th></tr></thead><tbody>{rows.map((a, index) => <tr key={a.appointment_id} style={{ '--row': Math.min(index, 8) }}><td><button className="person-cell" onClick={() => open({ type: 'history', item: { patient_id: a.patient_id, first_name: a.patient_name } })}><span className={`avatar color-${index % 4}`}>{initials(a.patient_name)}</span><span><strong>{a.patient_name}</strong><small>Patient #{String(a.patient_id).padStart(4, '0')}</small></span></button></td><td><span className="time-cell"><Clock3 size={13} />{a.appointment_time.slice(0, 5)}</span><small className="cell-sub">{compact ? `${a.duration_minutes} min consultation` : dateLabel(a.appointment_date)}</small></td><td><strong className="cell-title">Dr. {a.doctor_name}</strong><small className="cell-sub">{a.dept_name}</small></td><td><Status value={a.status} /></td><td><div className="row-actions">
    {user.role === 'Admin' && a.status === 'Scheduled' && <><button className="icon-btn" title="Reschedule" aria-label={`Reschedule appointment ${a.appointment_id}`} onClick={() => open({ type: 'reschedule', item: a })}><Pencil size={15} /></button><button className="icon-btn danger" title="Cancel appointment" aria-label={`Cancel appointment ${a.appointment_id}`} onClick={() => open({ type: 'cancel', item: a })}><X size={17} /></button>{`${a.appointment_date}T${a.appointment_time}` < `${clinicDate()}T${new Date().toLocaleTimeString('en-GB', { timeZone: 'Asia/Kolkata' })}` && <button className="text-btn" onClick={() => action(`/appointments/${a.appointment_id}/status`, 'PATCH', { status: 'No_Show' }, 'Appointment marked as no-show.')}>No-show</button>}</>}
    {user.role === 'Doctor' && a.status === 'Scheduled' && <button className="btn secondary small" onClick={() => action(`/appointments/${a.appointment_id}/status`, 'PATCH', { status: 'In_Consultation' }, 'Consultation started.')}>Start visit <ArrowRight size={14} /></button>}
    {user.role === 'Doctor' && a.status === 'In_Consultation' && <button className="btn primary small" onClick={() => open({ type: 'encounter', item: a })}>Open encounter</button>}
    {a.status === 'Completed' && <button className="text-btn" onClick={() => open({ type: 'history', item: { patient_id: a.patient_id, first_name: a.patient_name } })}>View record <ArrowUpRight size={14} /></button>}
    {['Cancelled', 'No_Show'].includes(a.status) && <span className="muted">Retained</span>}
    {user.role === 'Admin' && a.status === 'In_Consultation' && <span className="muted">With doctor</span>}
  </div></td></tr>)}</tbody></table></div>;
}

function Overview({ data, user, open, go, action }) {
  const todayQuery = useData(`/appointments?appointment_date=${clinicDate()}`);
  const rows = todayQuery.data || [];
  const stats = user.role === 'Admin'
    ? [[CalendarDays, data.appointments_today, 'Appointments today', `${data.waiting_today} scheduled visits`, 'teal'], [Users, data.patients, 'Registered patients', 'Connected patient records', 'violet'], [Wallet, money(data.collected_today), 'Collected today', 'Recorded clinic payments', 'blue'], [Pill, data.low_stock, 'Stock alerts', 'Medicines at reorder level', 'amber']]
    : [[CalendarDays, data.appointments_today, 'Your appointments', `${data.waiting_today} scheduled visits`, 'teal'], [CheckCircle2, data.completed_today, 'Completed today', 'Clinical encounters finalized', 'violet'], [Users, data.patients, 'Your patients', 'Across your appointments', 'blue'], [Pill, data.low_stock, 'Stock alerts', 'Check before prescribing', 'amber']];
  return <><section className="welcome-banner"><div><span className="eyebrow">A WELL-CONNECTED DAY STARTS HERE</span><h2>Great care starts<br />with a clear picture.</h2><p>Your appointments, patients, and clinic operations. All in sync.</p><button className="btn light" onClick={() => user.role === 'Admin' ? open({ type: 'booking' }) : go('consultations')}>{user.role === 'Admin' ? 'Book an appointment' : 'View your consultations'} <ArrowRight size={17} /></button></div><div className="banner-visual" aria-hidden="true"><div className="visual-ring ring-1" /><div className="visual-ring ring-2" /><div className="visual-plus"><HeartPulse size={62} strokeWidth={1.5} /></div><div className="floating-tag tag-1"><CheckCircle2 size={18} /><span>Connected care<strong>Every step, together.</strong></span></div><div className="floating-tag tag-2"><Activity size={17} /><span>Clinic pulse<strong>{data.active_doctors} active doctors</strong></span></div><svg className="pulse-line" viewBox="0 0 400 140"><path d="M0 75 H95 L110 60 L125 92 L145 15 L170 125 L190 65 L210 75 H400" /></svg></div></section>
    <section className="stats-grid">{stats.map(([Icon, value, label, description, color], i) => <article className="stat-card" key={label} style={{ animationDelay: `${i * 65}ms` }}><div className="stat-top"><span className={`stat-icon ${color}`}><Icon size={20} /></span><ArrowUpRight size={16} className="muted" /></div><div className="stat-value">{value}</div><h3>{label}</h3><p><span className={`tiny-dot ${color}`} />{description}</p></article>)}</section>
    <div className="overview-columns"><section className="panel appointments-panel"><div className="section-heading"><div><span className="eyebrow">THE DAILY LINEUP</span><h2>Today’s appointments <span className="count-badge">{rows.length}</span></h2></div><button className="text-btn" onClick={() => go('appointments')}>View schedule <ArrowRight size={15} /></button></div>{todayQuery.isPending ? <Loading /> : todayQuery.error ? <ErrorState error={todayQuery.error} retry={todayQuery.refetch} /> : <AppointmentTable rows={rows.slice(0, 5)} user={user} open={open} action={action} compact />}</section>
      <aside className="panel clinic-pulse"><div className="section-heading"><div><span className="eyebrow">IN THE LOOP</span><h2>Clinic snapshot</h2></div><Activity size={20} /></div><div className="pulse-summary"><span className="pulse-blob"><HeartPulse size={27} /></span><div><strong>{data.active_doctors} doctors</strong><p>Available across specialties</p></div></div><div className="snapshot-row"><span>Visits completed today</span><b>{data.completed_today}</b></div><div className="snapshot-row"><span>Scheduled for today</span><b>{data.waiting_today}</b></div><div className="snapshot-row"><span>Inventory alerts</span><b className={data.low_stock ? 'amber-text' : ''}>{data.low_stock}</b></div><div className="care-note"><Sparkles size={18} /><p>A little preparation goes a long way. Review pharmacy alerts before your next encounter.</p></div><button className="btn secondary full-width" onClick={() => go('pharmacy')}>Open pharmacy <ArrowRight size={15} /></button></aside></div>
    {user.role === 'Admin' && <section className="panel revenue-panel"><div className="section-heading"><div><span className="eyebrow">ACROSS SPECIALTIES</span><h2>Department collections</h2><p>All recorded paid invoices · amounts in INR</p></div><button className="text-btn" onClick={() => go('reports')}>Explore reports <ArrowUpRight size={16} /></button></div><div className="revenue-bars">{data.revenue?.map((r, i) => <div className="revenue-bar" key={r.dept_name}><div><span>{r.dept_name}</span><strong>{money(r.revenue)}</strong></div><div className="bar-track"><span style={{ width: `${Math.max(1, Number(r.revenue) / Math.max(...data.revenue.map(item => Number(item.revenue)), 1) * 100)}%`, animationDelay: `${i * 100}ms` }} /></div></div>)}</div></section>}
  </>;
}

function Reports() {
  const [report, setReport] = useState('department-revenue');
  const [patient, setPatient] = useState('1');
  const choices = [['department-revenue', 'Department revenue', 'CTE · joins · ranking'], ['doctor-performance', 'Doctor performance', 'Aggregates · outer joins'], ['pharmacy-reorder', 'Pharmacy reorder', 'CTEs · stock velocity'], ['patient-history', 'Patient history', 'Subquery · JSON aggregation'], ['peak-demand', 'Peak demand', 'Grouping · window rank']];
  const query = useData(`/reports/${report}${report === 'patient-history' ? `?patient_id=${patient || '0'}` : ''}`);
  const columns = query.data?.length ? Object.keys(query.data[0]) : [];
  const display = value => value === null ? '—' : typeof value === 'object' ? JSON.stringify(value) : String(value).replaceAll('_', ' ');
  function download() {
    if (!query.data?.length) return;
    const escape = v => { const text = display(v); return `"${(/^[=+@\-\t\r]/.test(text) ? "'" + text : text).replaceAll('"', '""')}"`; };
    const content = '\uFEFF' + [columns.map(escape).join(','), ...query.data.map(row => columns.map(c => escape(row[c])).join(','))].join('\r\n');
    const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([content], { type: 'text/csv;charset=utf-8' })); link.download = `medconnect-${report}.csv`; link.click(); URL.revokeObjectURL(link.href);
  }
  return <><div className="report-options">{choices.map(([key, title, detail]) => <button key={key} className={`report-option ${report === key ? 'active' : ''}`} onClick={() => setReport(key)}><FileText size={20} /><strong>{title}</strong><small>{detail}</small>{report === key && <CheckCircle2 size={16} className="option-check" />}</button>)}</div><section className="panel"><div className="section-heading"><div><span className="eyebrow">DATABASE INSIGHTS</span><h2>{choices.find(r => r[0] === report)[1]}</h2><p>{report === 'department-revenue' ? 'Current calendar month · paid collections and pending balances' : report === 'doctor-performance' ? 'Last 30 days through today · attendance among completed and no-show visits' : report === 'peak-demand' ? 'Last 90 days through today · appointment demand by day and hour' : report === 'pharmacy-reorder' ? 'Current stock, expiry, and dispensing over the last 30 days' : 'Recorded encounters with dispensed price snapshots'}</p></div><button className="btn secondary small" onClick={download} disabled={!query.data?.length}><ArrowDownLeft size={15} /> Export CSV</button></div>{report === 'patient-history' && <div className="toolbar"><Field label="Patient ID" type="number" min={1} value={patient} onChange={e => setPatient(e.target.value)} /></div>}{query.isPending ? <Loading /> : query.error ? <ErrorState error={query.error} retry={query.refetch} /> : !query.data.length ? <Empty title="No report rows for this selection" text="Try a patient with completed encounters or add workflow data." /> : <div className="table-wrap report-table"><table><thead><tr>{columns.map(c => <th key={c}>{c.replaceAll('_', ' ')}</th>)}</tr></thead><tbody>{query.data.map((row, i) => <tr key={i}>{columns.map(c => <td key={c}>{display(row[c])}</td>)}</tr>)}</tbody></table></div>}<div className="panel-foot"><ShieldCheck size={14} /> Results come directly from the five SQL reports in database/queries.</div></section></>;
}

export default function App() {
  const client = useQueryClient();
  const [signedIn, setSignedIn] = useState(hasToken());
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('overview');
  const [mobileNav, setMobileNav] = useState(false);
  const [modal, setModal] = useState(null);
  const [toast, setToast] = useState(null);
  const [search, setSearch] = useState('');
  const [day, setDay] = useState(clinicDate());
  const [status, setStatus] = useState('');
  const [billingFilter, setBillingFilter] = useState('');
  const auth = useData('/auth/me', signedIn && !user);
  useEffect(() => { if (auth.data) setUser(auth.data); }, [auth.data]);
  useEffect(() => { const expire = () => { setSignedIn(false); setUser(null); client.clear(); }; window.addEventListener('session-expired', expire); return () => window.removeEventListener('session-expired', expire); }, [client]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(null), 4500); return () => clearTimeout(timer); }, [toast]);
  const overview = useData('/overview', Boolean(user));
  const doctors = useData('/doctors', Boolean(user));
  const patients = useData(`/patients?q=${encodeURIComponent(search)}&limit=250`, Boolean(user) && page === 'patients');
  const appointments = useData(`/appointments?${day ? `appointment_date=${day}&` : ''}${status ? `status=${status}` : ''}`, Boolean(user) && ['appointments', 'consultations'].includes(page));
  const medicines = useData('/medicines', Boolean(user));
  const invoices = useData(`/invoices${billingFilter ? `?payment_status=${billingFilter}` : ''}`, user?.role === 'Admin' && page === 'billing');
  const mutation = useMutation({ mutationFn: ({ path, method, data }) => send(path, method, data), onSuccess: (_, variables) => { client.invalidateQueries(); setModal(null); setToast({ message: variables.message || 'Changes saved successfully.', type: 'success' }); }, onError: (error, variables) => { if (!variables.inDialog) setToast({ message: error.message, type: 'error' }); } });
  const action = (path, method, data, message, inDialog = false) => mutation.mutate({ path, method, data, message, inDialog });
  const open = value => { mutation.reset(); setModal(value); };
  const close = () => { if (!mutation.isPending) { setModal(null); mutation.reset(); } };
  const go = value => { setPage(value); setSearch(''); setStatus(''); setMobileNav(false); };
  const logout = () => { setToken(null); setUser(null); setSignedIn(false); setPage('overview'); setModal(null); client.clear(); };
  if (!signedIn) return <Login onLogin={value => { client.clear(); setUser(value); setSignedIn(true); }} />;
  if (!user) return <main className="session-loading">{auth.error ? <><ErrorState error={auth.error} retry={auth.refetch} /><button className="btn secondary" onClick={logout}>Back to sign in</button></> : <Loading />}</main>;
  const isAdmin = user.role === 'Admin';
  const currentNav = navItems.find(item => item[0] === page);
  const item = modal?.item;
  const formProps = { busy: mutation.isPending, error: mutation.error, close };
  const pageTitles = { overview: ['Your clinic, at a glance.', 'A clear view of the day. A little more space to focus on care.'], appointments: ['A well-planned day.', 'Book, reschedule, and keep every visit moving smoothly.'], patients: ['People, not just records.', 'A connected registry for a more personal care experience.'], consultations: ['Room for better care.', 'Your appointments, clinical notes, and prescriptions in one place.'], pharmacy: ['The right stock. On hand.', 'Keep an eye on availability, pricing, and the next reorder.'], billing: ['Every visit, accounted for.', 'Clear invoices and recorded payments, connected to each encounter.'], reports: ['See the bigger picture.', 'Five live SQL reports turn clinic activity into useful insight.'] };
  const overviewError = overview.error || doctors.error || medicines.error;
  return <div className="workspace"><button className={`nav-scrim ${mobileNav ? 'visible' : ''}`} onClick={() => setMobileNav(false)} aria-label="Close navigation" /><aside className={`sidebar ${mobileNav ? 'sidebar-open' : ''}`}><a className="brand" href="#" onClick={e => { e.preventDefault(); go('overview'); }}><span className="brand-icon"><HeartPulse size={27} /></span><span>MedConnect<small>CLINIC WORKSPACE</small></span></a><div className="workspace-label"><span className="clinic-icon"><Stethoscope size={18} /></span><div><strong>MedConnect Clinic</strong><span>Outpatient care · Hyderabad</span></div><span className="live-dot" /></div><p className="nav-label">WORKSPACE</p><nav aria-label="Main navigation">{navItems.filter(([id]) => isAdmin ? id !== 'consultations' : !['billing', 'reports'].includes(id)).map(([id, label, Icon]) => <button key={id} className={`nav-item ${page === id ? 'active' : ''}`} aria-current={page === id ? 'page' : undefined} onClick={() => go(id)}><Icon size={19} /><span>{label}</span>{id === 'pharmacy' && overview.data?.low_stock > 0 && <b className="nav-count">{overview.data.low_stock}</b>}{page === id && <i />}</button>)}</nav><div className="sidebar-bottom"><div className="connected-card"><span className="connected-icon"><ShieldCheck size={20} /></span><h3>One connected clinic.</h3><p>From the first appointment<br />to the final follow-up.</p><div><span className="live-dot" /> Connected to PostgreSQL</div></div><button className="profile" onClick={logout} title="Sign out"><span className="profile-avatar">{initials(user.name)}</span><span><strong>{user.role === 'Doctor' ? `Dr. ${user.name}` : 'Clinic Admin'}</strong><small>{isAdmin ? 'Administration' : 'Doctor workspace'}</small></span><LogOut size={17} /></button></div></aside>
    <div className="workspace-main"><header className="topbar"><div className="breadcrumb"><button className="icon-btn mobile-menu" onClick={() => setMobileNav(!mobileNav)} aria-label="Open navigation"><Menu size={21} /></button><span>Workspace</span><ChevronRight size={13} /><strong>{currentNav[1]}</strong></div><div className="topbar-right"><span className="today-label"><CalendarDays size={15} />{new Date().toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric', timeZone: 'Asia/Kolkata' })}</span><span className="topbar-divider" /><button className="icon-btn" onClick={() => client.invalidateQueries()} title="Refresh clinic data" aria-label="Refresh clinic data"><RefreshCw size={17} /></button><span className="top-avatar">{initials(user.name)}</span></div></header>
      <main className="page-content" key={page}><div className="page-heading"><div><span className="eyebrow">{page === 'overview' ? 'WELCOME TO YOUR WORKSPACE' : 'MEDCONNECT / ' + currentNav[1].toUpperCase()}</span><h1>{pageTitles[page][0]}</h1><p>{pageTitles[page][1]}</p></div>{isAdmin && ['overview', 'appointments'].includes(page) && <button className="btn primary" onClick={() => open({ type: 'booking' })}><Plus size={17} /> New appointment</button>}{isAdmin && page === 'patients' && <button className="btn primary" onClick={() => open({ type: 'patient' })}><Plus size={17} /> Register patient</button>}{isAdmin && page === 'pharmacy' && <button className="btn primary" onClick={() => open({ type: 'medicine' })}><Plus size={17} /> Add medicine</button>}</div>
      {overviewError && <ErrorState error={overviewError} retry={() => client.invalidateQueries()} />}
      {page === 'overview' && (overview.isPending ? <Loading /> : overview.data && <Overview data={overview.data} user={user} open={open} go={go} action={action} />)}
      {['appointments', 'consultations'].includes(page) && <section className="panel"><div className="section-heading"><div><h2>{page === 'consultations' ? 'Your consultation list' : 'Appointment schedule'}</h2><p>{day ? dateLabel(day) : 'Latest 250 visits'} · {appointments.data?.length || 0} visits</p></div><span className="panel-symbol"><CalendarDays size={21} /></span></div><div className="toolbar"><label className="filter-control"><CalendarDays size={16} /><input type="date" value={day} aria-label="Filter appointment date" onChange={e => setDay(e.target.value)} /></label><label className="filter-control"><SlidersHorizontal size={16} /><select aria-label="Filter appointment status" value={status} onChange={e => setStatus(e.target.value)}><option value="">All statuses</option>{['Scheduled', 'In_Consultation', 'Completed', 'Cancelled', 'No_Show'].map(v => <option key={v} value={v}>{v.replaceAll('_', ' ')}</option>)}</select></label><button className="text-btn" onClick={() => setDay(clinicDate())}>Today</button><button className="text-btn" onClick={() => setDay(nextDate())}>Tomorrow</button><button className="text-btn" onClick={() => setDay('')}>All dates</button></div>{appointments.isPending ? <Loading /> : appointments.error ? <ErrorState error={appointments.error} retry={appointments.refetch} /> : <AppointmentTable rows={appointments.data || []} user={user} open={open} action={action} />}<div className="panel-foot"><ShieldCheck size={14} /> Cancelled appointments stay in the record. Their slots become available again.</div></section>}
      {page === 'patients' && <section className="panel"><div className="section-heading"><div><h2>{isAdmin ? 'Patient directory' : 'Your patient directory'}</h2><p>{patients.data?.length || 0} matching records · up to 250 results</p></div><span className="panel-symbol"><Users size={21} /></span></div><div className="toolbar"><label className="search-control"><Search size={17} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search patients by name or phone…" aria-label="Search patients" /></label><span className="muted">{isAdmin ? 'Clinic patient registry' : 'Patients with your appointments'}</span></div>{patients.isPending ? <Loading /> : patients.error ? <ErrorState error={patients.error} retry={patients.refetch} /> : !patients.data?.length ? <Empty title="No matching patients" text="Try another name or phone number." /> : <div className="table-wrap"><table><thead><tr><th>Patient</th><th>Contact</th><th>Date of birth</th><th>Blood group</th><th className="align-right">Actions</th></tr></thead><tbody>{patients.data.map((p, i) => <tr key={p.patient_id}><td><div className="person-cell"><span className={`avatar color-${i % 4}`}>{initials(p.first_name + ' ' + p.last_name)}</span><span><strong>{p.first_name} {p.last_name}</strong><small>#{String(p.patient_id).padStart(4, '0')} · {p.gender}</small></span></div></td><td><strong className="cell-title">{p.phone}</strong><small className="cell-sub">{p.email || 'No email recorded'}</small></td><td>{dateLabel(p.date_of_birth)}</td><td><span className="blood-badge">{p.blood_group || '—'}</span></td><td><div className="row-actions"><button className="text-btn" onClick={() => open({ type: 'history', item: p })}>History <ArrowUpRight size={14} /></button>{isAdmin && <><button className="icon-btn" aria-label={`Edit patient ${p.patient_id}`} onClick={() => open({ type: 'patient', item: p })}><Pencil size={15} /></button><button className="icon-btn danger" aria-label={`Delete patient ${p.patient_id}`} onClick={() => open({ type: 'delete-patient', item: p })}><Trash2 size={15} /></button></>}</div></td></tr>)}</tbody></table></div>}</section>}
      {page === 'pharmacy' && <><div className="mini-stats"><div><span className="stat-icon teal"><Pill size={19} /></span><span><strong>{medicines.data?.length || 0}</strong>Catalog medicines</span></div><div><span className="stat-icon amber"><PackagePlus size={19} /></span><span><strong>{medicines.data?.filter(m => m.needs_reorder).length || 0}</strong>At reorder level</span></div><div><span className="stat-icon violet"><ShieldCheck size={19} /></span><span><strong>Price snapshots</strong>Preserved on dispensing</span></div></div><section className="panel"><div className="section-heading"><div><h2>Pharmacy inventory</h2><p>Stock updates as consultations are completed.</p></div><span className="panel-symbol"><Pill size={21} /></span></div><div className="toolbar"><label className="search-control"><Search size={17} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search medicines or category…" aria-label="Search medicines" /></label><span className="muted">All prices in INR</span></div>{medicines.isPending ? <Loading /> : medicines.error ? <ErrorState error={medicines.error} retry={medicines.refetch} /> : <div className="table-wrap"><table><thead><tr><th>Medicine</th><th>Category</th><th>Unit price</th><th>Stock</th><th>Expiry</th>{isAdmin && <th className="align-right">Actions</th>}</tr></thead><tbody>{medicines.data.filter(m => `${m.name} ${m.category}`.toLowerCase().includes(search.toLowerCase())).map(m => <tr key={m.medicine_id}><td><div className="person-cell"><span className="medicine-avatar"><Pill size={19} /></span><span><strong>{m.name}</strong><small>{m.manufacturer}</small></span></div></td><td>{m.category}</td><td className="money-text">{money(m.unit_price)}</td><td><strong className={m.needs_reorder ? 'amber-text' : 'stock-healthy'}>{m.stock_quantity} units</strong><small className="cell-sub">Reorder at {m.reorder_level}{m.needs_reorder ? ' · Low stock' : ''}</small></td><td>{dateLabel(m.expiry_date)}{m.expired && <span className="expired-badge">Expired</span>}</td>{isAdmin && <td><div className="row-actions"><button className="text-btn" onClick={() => open({ type: 'restock', item: m })}><Plus size={14} /> Restock</button><button className="icon-btn" aria-label={`Update price for ${m.name}`} onClick={() => open({ type: 'price', item: m })}><Pencil size={15} /></button></div></td>}</tr>)}</tbody></table></div>}</section></>}
      {page === 'billing' && <><div className="mini-stats"><div><span className="stat-icon teal"><Wallet size={19} /></span><span><strong>{money(overview.data?.collected_today)}</strong>Collected today</span></div><div><span className="stat-icon amber"><Clock3 size={19} /></span><span><strong>{money(overview.data?.outstanding)}</strong>Outstanding clinic balance</span></div><div><span className="stat-icon violet"><FileText size={19} /></span><span><strong>One encounter. One invoice.</strong>Amounts stay fixed after issue</span></div></div><section className="panel"><div className="section-heading"><div><h2>Encounter invoices</h2><p>Latest 250 invoices · consultation and pharmacy charges</p></div><label className="filter-control"><SlidersHorizontal size={16} /><select aria-label="Filter payment status" value={billingFilter} onChange={e => setBillingFilter(e.target.value)}><option value="">All invoices</option><option>Pending</option><option>Paid</option></select></label></div>{invoices.isPending ? <Loading /> : invoices.error ? <ErrorState error={invoices.error} retry={invoices.refetch} /> : !invoices.data.length ? <Empty title="No invoices in this view" text="Invoices are issued when a doctor completes an encounter." /> : <div className="table-wrap"><table><thead><tr><th>Invoice / patient</th><th>Consultation</th><th>Pharmacy</th><th>Total</th><th>Status</th><th className="align-right">Action</th></tr></thead><tbody>{invoices.data.map(i => <tr key={i.invoice_id}><td><strong className="cell-title">{i.patient_name}</strong><small className="cell-sub">INV-{String(i.invoice_id).padStart(4, '0')} · {dateLabel(i.appointment_date)}</small></td><td>{money(i.consultation_fee)}</td><td>{money(i.medicine_total)}</td><td className="money-text">{money(i.total_amount)}</td><td><Status value={i.payment_status} /></td><td className="align-right">{i.payment_status === 'Pending' ? <button className="btn secondary small" onClick={() => open({ type: 'payment', item: i })}>Record payment <ArrowRight size={14} /></button> : <span className="payment-method"><CheckCircle2 size={14} /> {i.payment_method}</span>}</td></tr>)}</tbody></table></div>}<div className="panel-foot"><ShieldCheck size={14} /> Recording a payment updates the paid-only department revenue view.</div></section></>}
      {page === 'reports' && <Reports />}
      <footer className="workspace-footer"><span><HeartPulse size={14} /> MedConnect · Connected clinic operations</span><span>Group-11 <i /> PostgreSQL 16 · FastAPI · React</span></footer></main></div>
    {toast && <div className={`toast toast-${toast.type}`} role={toast.type === 'error' ? 'alert' : 'status'}>{toast.type === 'error' ? <AlertCircle size={19} /> : <CheckCircle2 size={19} />}<span>{toast.message}</span><button onClick={() => setToast(null)} aria-label="Dismiss notification"><X size={16} /></button></div>}
    {modal?.type === 'patient' && <Modal title={item ? 'Update patient details' : 'Register a new patient'} subtitle="A few details to start a connected care record." close={close}><PatientForm patient={item} {...formProps} submit={data => action(`/patients${item ? `/${item.patient_id}` : ''}`, item ? 'PUT' : 'POST', data, item ? 'Patient details updated.' : 'Patient registered.', true)} /></Modal>}
    {['booking', 'reschedule'].includes(modal?.type) && <Modal title={item ? 'Find a better time' : 'Book an appointment'} subtitle="Choose a patient, doctor, and available time." close={close}><BookingForm appointment={item} doctors={doctors.data || []} {...formProps} submit={data => action(item ? `/appointments/${item.appointment_id}/reschedule` : '/appointments', item ? 'PATCH' : 'POST', data, item ? 'Appointment rescheduled.' : 'Appointment confirmed.', true)} /></Modal>}
    {modal?.type === 'encounter' && <Modal title="Clinical encounter" subtitle="Document the visit and complete the care workflow." close={close} wide><EncounterForm appointment={item} medicines={medicines.data || []} {...formProps} submit={data => action(`/appointments/${item.appointment_id}/complete`, 'POST', data, 'Encounter completed. Stock updated and invoice issued.', true)} /></Modal>}
    {modal?.type === 'history' && <Modal title={`${item.first_name}${item.last_name ? ' ' + item.last_name : ''}`} subtitle="Clinical history · completed and imported records" close={close} wide><History patient={item} /></Modal>}
    {modal?.type === 'medicine' && <Modal title="Add a catalog medicine" subtitle="Set the opening stock and reorder threshold." close={close}><MedicineForm {...formProps} submit={data => action('/medicines', 'POST', data, 'Medicine added to the catalog.', true)} /></Modal>}
    {modal?.type === 'restock' && <Modal title="Receive pharmacy stock" subtitle={`${item.name} · ${item.stock_quantity} units currently available`} close={close}><ValueForm {...formProps} label="Units received" numeric initial="25" button="Receive stock" submit={value => action(`/medicines/${item.medicine_id}/restock`, 'POST', { quantity: Number(value) }, 'Pharmacy stock updated.', true)} /></Modal>}
    {modal?.type === 'price' && <Modal title="Update catalog price" subtitle={`${item.name} · Previous dispenses retain their original price.`} close={close}><ValueForm {...formProps} label="New unit price (₹)" numeric="price" initial={item.unit_price} button="Update price" submit={value => action(`/medicines/${item.medicine_id}/price`, 'PATCH', { unit_price: value }, 'Catalog price updated.', true)} /></Modal>}
    {modal?.type === 'payment' && <Modal title="Record a clinic payment" subtitle="Confirm the payment method received at reception." close={close}><PaymentForm invoice={item} {...formProps} submit={data => action(`/invoices/${item.invoice_id}/pay`, 'POST', data, 'Payment recorded. Revenue report updated.', true)} /></Modal>}
    {['cancel', 'delete-patient'].includes(modal?.type) && <Modal title={modal.type === 'cancel' ? 'Cancel this appointment?' : 'Delete this patient?'} subtitle={modal.type === 'cancel' ? `${item.patient_name} · ${dateLabel(item.appointment_date)} at ${item.appointment_time.slice(0, 5)}` : `${item.first_name} ${item.last_name}`} close={close}><form onSubmit={e => { e.preventDefault(); modal.type === 'cancel' ? action(`/appointments/${item.appointment_id}/status`, 'PATCH', { status: 'Cancelled' }, 'Appointment cancelled. The slot is available again.', true) : action(`/patients/${item.patient_id}`, 'DELETE', undefined, 'Patient removed.', true); }}><p className="confirm-copy">{modal.type === 'cancel' ? 'The appointment stays in the clinic history. Its time slot will be released for a new booking.' : 'Only patients with no linked bookings or clinical records can be deleted. The database protects existing clinical history.'}</p>{mutation.error && <p className="form-error" role="alert">{mutation.error.message}</p>}<FormFooter busy={mutation.isPending} label={modal.type === 'cancel' ? 'Confirm cancellation' : 'Delete unlinked patient'} close={close} /></form></Modal>}
  </div>;
}
